const translations: Record<string, ComputerWords> = { zh: ZH, 'zh-Hant': ZH_HANT, es: ES, fr: FR, ko: KO, ja: JA, ru: RU }
const key = (locale: string) => { const l = locale.replace(/_/g, '-').toLowerCase(); return l.startsWith('zh') ? /hant|tw|hk|mo/.test(l) ? 'zh-Hant' : 'zh' : l.split('-')[0]! }
export function computerStrings(locale: string): ComputerWords { return translations[key(locale)] ?? EN }
/** DSH's own languages (dsh-client-locale), each named in itself, as DSH Desktop's language picker shows them. */
export const DSH_LANGUAGES: Record<string, string> = { zh: '中文', en: 'English', ja: '日本語', es: 'Español', fr: 'Français', de: 'Deutsch', ru: 'Русский', pt: 'Português' }
